{"@timestamp": "2020-09-22T06:16:08.623Z", "@version": "1", "AccountName": "pgustavo", "AccountType": "User", "ActivityID": "{3AF69DEC-79B4-0000-178C-1F856290D601}", "Category": "Executing Pipeline", "Channel": "Microsoft-Windows-PowerShell/Operational", "ContextInfo": "        Severity = Informational
